-- Generated by scripts/prepare-lesson-recovery.mjs from the reviewed exports.
-- Rebuilds only independently verified passed slide gates and training stages.
-- Does not invent answers, quiz scores, assessment results, or whole-unit completion.
-- Close learner app tabs first. Run the ENTIRE script; choose Run without RLS.
-- Requires the previously installed recovery backup table and private helper.
begin;
set local lock_timeout = '10s';
set local statement_timeout = '60s';
lock table public.app_state in share row exclusive mode;
lock table public.shared_state in share mode;
create temporary table lesson_recovery_result (
  learner text, unit_id text, result text, added_slide_gates integer,
  training_stage_added boolean
) on commit drop;
do $repair$
declare
  item jsonb;
  current_text text;
  merged jsonb;
  result_unit jsonb;
  prior_unit jsonb;
  added integer;
  training_added boolean;
  current_md5 text;
begin
  for item in select value from jsonb_array_elements($recovery_plan$[{"learner":"Mpumelelo Hlongwane","profile_id":"p_mrom65g0_ho04y","owner":"b4080237-546b-42a4-beb7-c8e55812f4f9","unit":"114046","quiz_key":"itss.lessonquiz.p_mrom65g0_ho04y.114046","quiz_md5":"c3f55a8403f5bcabef73c089789c2d71","step_key":"itss.lessonstep.p_mrom65g0_ho04y.114046","step_md5":"37693cfc748049e45d87b8c7d8b9aacd","built_md5":"22172c173c73c77c3d9e27e5174c0a78","edits_md5":null,"patch":{"units":{"114046":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.0":true,"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.9":true,"slidegate.10":true,"slidegate.11":true,"slidegate.12":true,"slidegate.13":true,"slidegate.14":true,"slidegate.15":true,"slidegate.16":true,"slidegate.17":true,"slidegate.18":true,"slidegate.19":true,"slidegate.20":true,"slidegate.21":true,"slidegate.22":true,"slidegate.23":true}}}}},{"learner":"Mpumelelo Hlongwane","profile_id":"p_mrom65g0_ho04y","owner":"b4080237-546b-42a4-beb7-c8e55812f4f9","unit":"114051","quiz_key":"itss.lessonquiz.p_mrom65g0_ho04y.114051","quiz_md5":"02938cba7e5421a398c876a2aa2787e2","step_key":"itss.lessonstep.p_mrom65g0_ho04y.114051","step_md5":"02e74f10e0327ad868d138f2b4fdd6f0","built_md5":null,"edits_md5":"68aad9b59c5498c7ef68e89a7eab681d","patch":{"units":{"114051":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.0":true,"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.9":true,"slidegate.10":true,"slidegate.11":true,"slidegate.12":true,"slidegate.13":true,"slidegate.14":true,"slidegate.15":true,"slidegate.16":true,"slidegate.17":true,"slidegate.18":true,"slidegate.19":true,"slidegate.20":true,"slidegate.21":true,"slidegate.22":true,"slidegate.23":true,"slidegate.24":true,"slidegate.25":true,"slidegate.26":true,"slidegate.27":true}}}}},{"learner":"Mpumelelo Hlongwane","profile_id":"p_mrom65g0_ho04y","owner":"b4080237-546b-42a4-beb7-c8e55812f4f9","unit":"8252","quiz_key":"itss.lessonquiz.p_mrom65g0_ho04y.8252","quiz_md5":"ecdc0d7fa1fb948c21d2c56a211796d2","step_key":"itss.lessonstep.p_mrom65g0_ho04y.8252","step_md5":"8f14e45fceea167a5a36dedd4bea2543","built_md5":null,"edits_md5":"6f6d3272316fc969daad8507bda69867","patch":{"units":{"8252":{"activities":{},"logbook":{"slidegate.7":true}}}}},{"learner":"Mpumelelo Hlongwane","profile_id":"p_mrom65g0_ho04y","owner":"b4080237-546b-42a4-beb7-c8e55812f4f9","unit":"HWSW2","quiz_key":"itss.lessonquiz.p_mrom65g0_ho04y.HWSW2","quiz_md5":"86d61b058a10f93444d7405658b07d02","step_key":"itss.lessonstep.p_mrom65g0_ho04y.HWSW2","step_md5":"72b32a1f754ba1c09b3695e0cb6cde7f","built_md5":null,"edits_md5":null,"patch":{"units":{"HWSW2":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.57":true}}}}},{"learner":"Ntokozo Ngcobo","profile_id":"p_mromq49w_0jfmq","owner":"0167b875-b652-4bfd-aa52-86a7442c8ba5","unit":"114046","quiz_key":"itss.lessonquiz.p_mromq49w_0jfmq.114046","quiz_md5":"8e3764151fdbf47f4b9ca6e2e7f83a2f","step_key":"itss.lessonstep.p_mromq49w_0jfmq.114046","step_md5":"37693cfc748049e45d87b8c7d8b9aacd","built_md5":"22172c173c73c77c3d9e27e5174c0a78","edits_md5":null,"patch":{"units":{"114046":{"activities":{},"logbook":{"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.12":true}}}}},{"learner":"Ntokozo Ngcobo","profile_id":"p_mromq49w_0jfmq","owner":"0167b875-b652-4bfd-aa52-86a7442c8ba5","unit":"HWSW2","quiz_key":"itss.lessonquiz.p_mromq49w_0jfmq.HWSW2","quiz_md5":"90b98d615306cae5c758f5ba7a6f31dc","step_key":"itss.lessonstep.p_mromq49w_0jfmq.HWSW2","step_md5":"72b32a1f754ba1c09b3695e0cb6cde7f","built_md5":null,"edits_md5":null,"patch":{"units":{"HWSW2":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.9":true,"slidegate.10":true,"slidegate.11":true,"slidegate.12":true,"slidegate.13":true,"slidegate.14":true,"slidegate.15":true,"slidegate.16":true,"slidegate.17":true,"slidegate.18":true,"slidegate.19":true,"slidegate.20":true,"slidegate.21":true,"slidegate.22":true,"slidegate.23":true,"slidegate.24":true,"slidegate.25":true,"slidegate.26":true,"slidegate.27":true,"slidegate.28":true,"slidegate.29":true,"slidegate.30":true,"slidegate.31":true,"slidegate.32":true,"slidegate.33":true,"slidegate.34":true,"slidegate.35":true,"slidegate.36":true,"slidegate.38":true,"slidegate.39":true,"slidegate.40":true,"slidegate.41":true,"slidegate.42":true,"slidegate.43":true,"slidegate.44":true,"slidegate.45":true,"slidegate.46":true,"slidegate.47":true,"slidegate.48":true,"slidegate.49":true,"slidegate.50":true,"slidegate.51":true,"slidegate.52":true,"slidegate.53":true,"slidegate.54":true,"slidegate.55":true,"slidegate.56":true,"slidegate.57":true}}}}},{"learner":"Pontsho Molekane","profile_id":"p_mrom0udn_jcpeg","owner":"fdc7dbcb-d492-4045-ba81-aaad6ef50f26","unit":"114046","quiz_key":"itss.lessonquiz.p_mrom0udn_jcpeg.114046","quiz_md5":"2c4a6fb91013cc369c10ea5eaf2151de","step_key":"itss.lessonstep.p_mrom0udn_jcpeg.114046","step_md5":"37693cfc748049e45d87b8c7d8b9aacd","built_md5":"22172c173c73c77c3d9e27e5174c0a78","edits_md5":null,"patch":{"units":{"114046":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.9":true,"slidegate.10":true,"slidegate.12":true,"slidegate.13":true,"slidegate.14":true,"slidegate.15":true,"slidegate.16":true,"slidegate.17":true,"slidegate.18":true,"slidegate.19":true,"slidegate.20":true,"slidegate.21":true,"slidegate.22":true,"slidegate.23":true}}}}},{"learner":"Pontsho Molekane","profile_id":"p_mrom0udn_jcpeg","owner":"fdc7dbcb-d492-4045-ba81-aaad6ef50f26","unit":"114051","quiz_key":"itss.lessonquiz.p_mrom0udn_jcpeg.114051","quiz_md5":"c94ea06c0ea9ced1e65cadfd7e3d438f","step_key":"itss.lessonstep.p_mrom0udn_jcpeg.114051","step_md5":"02e74f10e0327ad868d138f2b4fdd6f0","built_md5":null,"edits_md5":"68aad9b59c5498c7ef68e89a7eab681d","patch":{"units":{"114051":{"activities":{"Lesson & Training Aids":true},"logbook":{"slidegate.0":true,"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true,"slidegate.8":true,"slidegate.9":true,"slidegate.10":true,"slidegate.11":true,"slidegate.12":true,"slidegate.13":true,"slidegate.14":true,"slidegate.15":true,"slidegate.16":true,"slidegate.17":true,"slidegate.18":true,"slidegate.19":true,"slidegate.20":true,"slidegate.21":true,"slidegate.22":true,"slidegate.23":true,"slidegate.24":true,"slidegate.25":true,"slidegate.26":true,"slidegate.27":true}}}}},{"learner":"Pontsho Molekane","profile_id":"p_mrom0udn_jcpeg","owner":"fdc7dbcb-d492-4045-ba81-aaad6ef50f26","unit":"HWSW2","quiz_key":"itss.lessonquiz.p_mrom0udn_jcpeg.HWSW2","quiz_md5":"878dd48c64ca63b6247bca922f79756a","step_key":"itss.lessonstep.p_mrom0udn_jcpeg.HWSW2","step_md5":"c9f0f895fb98ab9159f51fd0297e236d","built_md5":null,"edits_md5":null,"patch":{"units":{"HWSW2":{"activities":{},"logbook":{"slidegate.1":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"slidegate.7":true}}}}}]$recovery_plan$::jsonb) loop
    select md5(value) into current_md5 from public.app_state
      where tenant_id = 'investec' and user_id = (item ->> 'owner')::uuid
        and key = item ->> 'quiz_key';
    if current_md5 is distinct from item ->> 'quiz_md5' then
      insert into lesson_recovery_result values (item ->> 'learner', item ->> 'unit', 'Skipped: saved quiz changed; export again', 0, false);
      continue;
    end if;
    select md5(value) into current_md5 from public.shared_state
      where tenant_id = 'investec' and key = 'itss.unitbuilder.' || (item ->> 'unit') || '.shared';
    if current_md5 is distinct from item ->> 'built_md5' then
      raise exception 'Unit content changed for %. No repairs committed.', item ->> 'unit';
    end if;
    select md5(value) into current_md5 from public.shared_state
      where tenant_id = 'investec' and key = 'itss.lessonedits.' || (item ->> 'unit');
    if current_md5 is distinct from item ->> 'edits_md5' then
      raise exception 'Quiz definitions changed for %. No repairs committed.', item ->> 'unit';
    end if;
    -- The final-slide position must still be the reviewed one before adding training credit.
    if (item #> array['patch','units',item ->> 'unit','activities']) ? 'Lesson & Training Aids' then
      select md5(value) into current_md5 from public.app_state
        where tenant_id = 'investec' and user_id = (item ->> 'owner')::uuid and key = item ->> 'step_key';
      if current_md5 is distinct from item ->> 'step_md5' then
        insert into lesson_recovery_result values (item ->> 'learner', item ->> 'unit', 'Skipped: lesson position changed; export again', 0, false);
        continue;
      end if;
    end if;
    select value into strict current_text from public.app_state
      where tenant_id = 'investec' and user_id = (item ->> 'owner')::uuid
        and key = 'itss.progress.' || (item ->> 'profile_id');
    if jsonb_typeof(current_text::jsonb -> 'units') is distinct from 'object' then
      raise exception 'Unexpected progress format for %.', item ->> 'learner';
    end if;
    insert into learner_recovery_private.progress_backup
      (batch_id,tenant_id,user_id,key,value,updated_at)
    select '2026-10-16-verified-lessons-v2',tenant_id,user_id,key,value,updated_at
      from public.app_state where tenant_id = 'investec' and user_id = (item ->> 'owner')::uuid
        and key in ('itss.progress.' || (item ->> 'profile_id'), item ->> 'quiz_key', item ->> 'step_key')
    on conflict do nothing;
    merged := learner_recovery_private.keep_missing_fields(current_text::jsonb, item -> 'patch');
    prior_unit := coalesce(current_text::jsonb #> array['units',item ->> 'unit'], '{}'::jsonb);
    result_unit := merged #> array['units',item ->> 'unit'];
    select count(*) into added from jsonb_each(coalesce(result_unit -> 'logbook','{}'::jsonb)) e
      where e.key like 'slidegate.%' and e.value = 'true'::jsonb
        and not (coalesce(prior_unit -> 'logbook','{}'::jsonb) ? e.key);
    training_added := coalesce(result_unit #>> '{activities,Lesson & Training Aids}', 'false') = 'true'
      and coalesce(prior_unit #>> '{activities,Lesson & Training Aids}', 'false') <> 'true';
    if merged is distinct from current_text::jsonb then
      update public.app_state set value = merged::text,updated_at = now()
        where tenant_id = 'investec' and user_id = (item ->> 'owner')::uuid
          and key = 'itss.progress.' || (item ->> 'profile_id');
    end if;
    insert into lesson_recovery_result values (item ->> 'learner',item ->> 'unit',
      case when merged is distinct from current_text::jsonb then 'Verified lesson progress restored'
        else 'Already present; current values preserved' end,added,training_added);
  end loop;
end;
$repair$;
select * from lesson_recovery_result order by learner,unit_id;
commit;
